import { Router } from 'express';
import { createWriteStream, existsSync } from 'node:fs';
import { access, constants, rename, rm } from 'node:fs/promises';
import { pipeline } from 'node:stream/promises';
import path from 'node:path';
import { requireAuth } from './auth.js';

export const DATA_DIR = process.env.DATA_DIR ?? '/data/videos';
const MAX_BYTES = Number(process.env.MAX_UPLOAD_MB ?? 500) * 1024 * 1024;

// Keys are UUIDs generated by the upload service. Checking the format also
// blocks path traversal like "../../etc/passwd".
const KEY = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

const router = Router();

// Save a video: PUT /files/<uuid> with the raw file as the body
router.put('/files/:key', requireAuth, async (req, res) => {
  const key = String(req.params.key);
  if (!KEY.test(key)) return void res.status(400).json({ error: 'key must be a UUID' });

  if (!req.headers['content-type']?.startsWith('video/')) {
    return void res.status(415).json({ error: 'only video/* content types are accepted' });
  }

  const size = Number(req.headers['content-length']);
  if (!size) return void res.status(411).json({ error: 'content-length required' });
  if (size > MAX_BYTES) return void res.status(413).json({ error: 'file too large' });

  const finalPath = path.join(DATA_DIR, key);
  if (existsSync(finalPath)) return void res.status(409).json({ error: 'key already exists' });

  // Write to a temp file and rename at the end, so a failed upload never
  // leaves a half-written video that could be streamed.
  const tmpPath = `${finalPath}.part`;
  try {
    await pipeline(req, createWriteStream(tmpPath));
    await rename(tmpPath, finalPath);
  } catch (err) {
    await rm(tmpPath, { force: true });
    throw err;
  }

  console.log(`stored ${key} (${size} bytes) for user ${res.locals.user?.sub}`);
  res.status(201).json({ key, size });
});

// Read a video. sendFile handles Range requests (206), which is what lets
// the browser's video player seek without downloading the whole file.
router.get('/files/:key', requireAuth, (req, res) => {
  const key = String(req.params.key);
  if (!KEY.test(key)) return void res.status(400).json({ error: 'key must be a UUID' });

  res.sendFile(key, { root: DATA_DIR }, (err) => {
    if (err && !res.headersSent) res.status(404).json({ error: 'not found' });
  });
});

// Remove a video (e.g. upload service cleaning up after a failed DB insert)
router.delete('/files/:key', requireAuth, async (req, res) => {
  const key = String(req.params.key);
  if (!KEY.test(key)) return void res.status(400).json({ error: 'key must be a UUID' });

  const filePath = path.join(DATA_DIR, key);
  if (!existsSync(filePath)) return void res.status(404).json({ error: 'not found' });
  await rm(filePath);
  res.status(204).end();
});

// Healthy = the video folder exists and is writable
router.get('/health', async (_req, res) => {
  try {
    await access(DATA_DIR, constants.W_OK);
    res.json({ status: 'ok' });
  } catch {
    res.status(503).json({ status: 'storage not writable' });
  }
});

export default router;